using System;
using System.Collections.Generic;

// Define the Item class with properties and methods
public class Item
{
    public string Name { get; set; }
    public string Description { get; set; }
    public int Quantity { get; set; }

    public Item(string name, string description, int quantity)
    {
        Name = name;
        Description = description;
        Quantity = quantity;
    }

    public void DisplayItemDetails()
    {
        Console.WriteLine($"Name: {Name}");
        Console.WriteLine($"Description: {Description}");
        Console.WriteLine($"Quantity: {Quantity}");
        Console.WriteLine();
    }
}

// Define the ItemCollection class to manage a collection of items
public class ItemCollection
{
    private List<Item> items;

    public ItemCollection()
    {
        items = new List<Item>();
    }

    // Method to add an item to the collection
    public void AddItem(string name, string description, int quantity)
    {
        Item newItem = new Item(name, description, quantity);
        items.Add(newItem);
    }

    // Method to remove an item from the collection
    public void RemoveItem(string name)
    {
        Item itemToRemove = items.Find(item => item.Name == name);
        if (itemToRemove != null)
        {
            items.Remove(itemToRemove);
        }
    }

    // Method to update the quantity of an item
    public void UpdateQuantity(string name, int newQuantity)
    {
        Item itemToUpdate = items.Find(item => item.Name == name);
        if (itemToUpdate != null)
        {
            itemToUpdate.Quantity = newQuantity;
        }
    }

    // Method to display the details of all items in the collection
    public void DisplayAllItems()
    {
        foreach (Item item in items)
        {
            item.DisplayItemDetails();
        }
    }
}

// Example usage of the Item and ItemCollection classes
class Program
{
    static void Main()
    {
        ItemCollection itemCollection = new ItemCollection();

        // Adding items to the collection
        itemCollection.AddItem("Apple", "Red and crunchy", 50);
        itemCollection.AddItem("Banana", "Yellow and sweet", 30);

        // Displaying all items
        itemCollection.DisplayAllItems();

        // Updating the quantity of an item
        itemCollection.UpdateQuantity("Apple", 75);

        // Displaying all items after updating
        itemCollection.DisplayAllItems();

        // Removing an item from the collection
        itemCollection.RemoveItem("Banana");

        // Displaying all items after removing
        itemCollection.DisplayAllItems();
    }
}
